import{_ as a,c as e,o as t,ae as o}from"./chunks/framework.BvcDoAct.js";const T=JSON.parse('{"title":"06 LEO 的故事","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/RockInOnJapan_BF/6_LEO.md","filePath":"zh-cn/RockInOnJapan_BF/6_LEO.md"}'),n={name:"zh-cn/RockInOnJapan_BF/6_LEO.md"};function B(E,p,S,r,I,c){return t(),e("div",null,[...p[0]||(p[0]=[o('<h1 id="_06-leo-的故事" tabindex="-1">06 LEO 的故事 <a class="header-anchor" href="#_06-leo-的故事" aria-label="Permalink to &quot;06 LEO 的故事&quot;">​</a></h1><h2 id="比任何人都更明亮、却又时而严厉的真实用意是什么-以爱与奉献支撑的「be-first」团队形态" tabindex="-1">比任何人都更明亮、却又时而严厉的真实用意是什么？以爱与奉献支撑的「BE:FIRST」团队形态 <a class="header-anchor" href="#比任何人都更明亮、却又时而严厉的真实用意是什么-以爱与奉献支撑的「be-first」团队形态" aria-label="Permalink to &quot;比任何人都更明亮、却又时而严厉的真实用意是什么？以爱与奉献支撑的「BE:FIRST」团队形态&quot;">​</a></h2><p>「（一边看着《JAPAN 2023年5月号》的个人采访一边说）这个，是大概3年前啊。那当然很年轻了。感觉还挺受欢迎的样子（笑）」</p><p>●（笑）从这次采访到现在也过了一段时间，BE:FIRST也进入第5年了，首先恭喜你们发行最佳专辑。</p><p>「谢谢！」</p><p>● 现在再回头看，真的很浓缩啊。歌曲数量很多，风格跨度也很大。而且这样排在一起听，会强烈感受到变化和成长。连声音都不一样了。</p><p>「是的。“Shining One”是为了这次最佳专辑重新录制的，但像“Be Free”“Move On”这些真的很青涩，甚至会觉得‘我当时是这样唱的吗’，多少有点不好意思。」</p><p>● 当然，当时有当时的魅力，现在也有现在的魅力。比如把“Gifted.”的原版和管弦乐版放在一起听，感觉已经变成完全不同的歌曲了。</p><p>「发行“Gifted.”的时候，我们是那种‘我们的出道曲是“Gifted.”啊，很厉害吧’的感觉，但现在回听，会觉得多少有点逞强，还是挺青涩的。」</p><p>● 这也说明你们作为BE:FIRST确实走过了一段时间。另一方面，这次作为新曲，还翻唱改编了杰克逊5的名曲“I Want You Back”。</p><p>「这个真的太厉害了。这不是随便能做到的事，所以也很感谢给予许可的人，还有努力促成这件事的工作人员和社长。真的完全没想到。一开始听到“I Want You Back”，我还以为只是这次新歌的名字。」</p><p>● 也就是说你以为是同名新曲。</p><p>「SOTA好像和社长讨论过这件事，但我完全不知道。日程上写着‘“I Want You Back”临时录音’，我就想‘哦，下首新歌是这个名字啊’。结果到了录音室，‘诶？真的假的？’那种感觉。第一次听到歌的时候，我觉得如果是采样的话也太大胆了，就问工作人员‘这个没问题吗？’他们却一脸‘啊？哪里有问题？’我说‘这不是几乎原样吗？’他们才说‘这是改编翻唱版’，我这才明白（笑）。」</p><p>● 你还以为只是采样（笑）。</p><p>「对啊。所以是在完全没搞清状况的情况下就开始临时录音了。现场的人应该都知道，就我一个人慌了。」</p><p>● 而且这还不只是普通翻唱。</p><p>「如果只是单纯翻唱我还能理解，但里面还有原创的rap，真的没想到。进展太快了。」</p><p>● 现在用全新的形式演绎杰克逊5的歌，本身就很有分量。毕竟是全球知名的作品，也一定会被比较。</p><p>「我觉得肯定会有批评。」</p><p>● 即便如此，你们也能说“这就是我们的风格，我们的‘I Want You Back’”了吧？</p><p>「是的。而且我自己是通过迈克尔·杰克逊认识杰克逊5的。以前不是有租CD的文化吗？我哥哥借了迈克尔的CD回来。因为不是新专辑，租起来很便宜，甚至会被放在小学生零花钱也能买的特价区。就是从那里开始了解杰克逊5的。所以能以这种形式翻唱，对我们来说真的像梦想实现了一样，非常荣幸。同时，我也希望大家在听我们的“I Want You Back”的同时，也能去听原曲。就像我从迈克尔认识到杰克逊5一样，虽然有点冒昧，但如果我们也能成为这样的桥梁就好了。希望不认识杰克逊5的年轻人会觉得‘原来还有这样的歌？’，然后去听原曲，觉得‘太厉害了！’虽然原曲的风格可能和现在的潮流有点不同，但音乐本身真的很棒，希望大家能去听。」</p><blockquote><p>回到家之后，我会觉得“BE:FIRST的LEO”这件事很不可思议。是成员、社长，还有身边的人，让我成为了“BE:FIRST的LEO”。</p></blockquote><p>● 在这首歌的评论里，SKY-HI提到杰克逊5是“现代男团的原型”。一直以来BE:FIRST更像是朝未来前进，但音乐背后其实有着连绵不断的历史，而杰克逊5也在其中。通过这首歌，你们也在宣告“BE:FIRST同样属于这段历史”。</p><p>「而且在最佳专辑这个时间点去做改编翻唱……就像连接过去与现在一样。能把这首歌作为主打，真的让我再次觉得能在这个团队里太好了。」</p><p>● 从外界看，可能只是“翻唱了经典名曲”，但我觉得这是BE:FIRST乃至BMSG迈向新领域的一步，是在思考“我们在更大的音乐叙事中处于什么位置”。</p><p>「谢谢。」</p><p>● 那回顾这一路，你有什么感受？</p><p>「这4年确实过得很快，但也很充实。最初登上巨蛋的时候，我甚至会想‘明天醒来会不会发现这一切是梦’。不过渐渐地，这种感觉没有了，这一年开始慢慢接受这一切就是现实。做了世界巡演，也上了很多节目、接受了采访，但回到家之后还是一个人嘛。那时候就会觉得‘自己其实很渺小’‘也没那么厉害’——」</p><p>● 你会这么想啊。</p><p>「会的。成员和后辈有时候还会说我像大叔（笑）。可能是因为我在公司里，洗完桑拿挂着毛巾看职业棒球的样子太有画面了。」</p><p>● 那确实像（笑）。</p><p>「但我一直就是这种类型，不怎么闪闪发光。我很憧憬父亲，也想成为像他那样的人。家里全是我喜欢的东西：有巨人队球员签名的球衣，玄关有经纪人送的生日垫子，再往里是手办展示柜，还有音乐房，客厅还有球棒和手套。这是我从小梦想的家，但我自己一点都不闪耀。每次回家都会觉得“BE:FIRST的LEO”很不可思议，会想‘我算什么啊’。所以我最近常常觉得，是成员、社长，还有周围的人，让我成为了BE:FIRST的LEO。」</p><p>● 在2023年的采访里你也说过：“如果长时间不和成员一起表演，就会担心自己回不去，会不会变回上村礼王。”</p><p>「这个现在也有。虽然知道自己是BE:FIRST的LEO，但总感觉有时候会分离。」</p><p>● 你从练习生时期就一直在理想和现实的差距中挣扎，这种感觉现在也还在？</p><p>「还在。不过我心里有一个开关。上舞台的时候不会这么想，因为我已经做好准备，也知道自己付出了努力，所以对这点是有自信的。但从16岁开始追逐这个梦想，已经7、8年了，这种感觉很难消失。有时候会恍惚觉得‘我是不是做了很厉害的事，会不会变成很厉害的人’，但马上会有另一个自己提醒‘不是你厉害，是周围的人厉害才让你看起来厉害’，然后我就会说‘是是，对不起（笑）’。」</p><p>● 实际上你确实很厉害，但这种自觉也成了你的动力。</p><p>「我本来就挺消极的，但正因为这样才会想努力。比如想被成员夸奖。无论是舞蹈还是唱歌，我从来没有觉得自己比成员强过。偶尔会觉得‘状态不错’，但从来没有‘太好了！’那种感觉。看过去的表演会觉得确实进步了，社长也说‘最近进步很大’，但我自己还是觉得不够。而且可能正因为我有点消极，所以才会表现得很开朗，大概是不想被讨厌吧。虽然可能有人会觉得这种开朗有点烦（笑）。」</p><p>● 这也是一种“消极发言”（笑）。不过正是这样的你，让BE:FIRST乃至BMSG受益很大。</p><p>「没有我可能也不会被发现（笑）。」</p><p>● 绝对不是。如果没有LEO，BE:FIRST不可能走到现在。</p><p>「要真是这样就好了。」</p><p>● 你以前说过“想成为能接住大家漏球的人”，同时也说过“发现即使没有我去维系，团队也能成立”。现在还在“接球”吗？</p><p>「最近反而觉得，在公司里……说得不好听一点，可能需要成为‘让人讨厌的角色’。」</p><p>● 就是说该说的话要说？</p><p>「要说别人不敢说的话，甚至是社长不方便说的话。社长其实很温柔，所以有些事情，比如‘那不对’这种话，可能需要我来说。尤其是在社长不在的时候，会有一种责任感。」</p><blockquote><p>对BMSG整体、对BE:FIRST来说，“麻烦的人”就是我的位置。没有这样的人，团队是无法成型的。</p></blockquote><p>● 为什么会觉得这是你的角色？</p><p>「从加入BE:FIRST开始，当大家讨论意见时，即使我赞成，也会说‘但这样想会不会也有另一种意义？’就像新选组一样，有近藤勇、有土方岁三、有冲田总司。土方通常比近藤更严厉一点，从而维持秩序。我觉得我可能是那个土方的角色。虽然社长可能会说‘别拿新选组来比（笑）’。社长作为BMSG的核心在上面，我们在下面，但不能把一切都交给他，必须自己也能运作。比如在“BMSG FES”上喊‘大家听我说！’这种事，就是我的职责。像是发号施令的人。虽然会被觉得很烦，但我觉得这就是我的位置。」</p><p>● 你在2023年也说过“‘麻烦的人’最适合自己”。</p><p>「因为没有这种人，团队就无法成立。个人的话只需要管理自己，但团队不一样。不能只考虑自己。人多了就容易变成‘反正会有人做’。我在棒球部就见过这种情况。并不是说BE:FIRST或BMSG是这样，但确实需要有人去做那个“麻烦的人”。如果有别人愿意做，我也想交给他，但在找到之前，我就会自己先动。」</p><p>● 有些人会从这种事情中获得快感。</p><p>「那种‘没有我不行’的感觉？」</p><p>● 但你不是那种人吧？</p><p>「完全不是（笑）。如果可以完全不说话无视一切，我更愿意那样。我也不想被讨厌，也不想被说‘又开始了’。但为了团队，我还是会说，希望有一天大家能理解。就像父母说的‘当了父母才会明白父母的心情’，我也不求他们现在就理解，但希望他们愿意去理解。有一天，当他们到了我这个年纪，也许会明白‘原来LEO说的是这个意思’。」</p><p>● 明明不想做，却一直承担这个角色，这就是LEO。</p><p>「这其实也是对社长的忠诚。我真的很喜欢他，也说过‘我把人生都交给社长了’。如果没有他，我不会想加入BE:FIRST。虽然也有说过让他受伤的话，但事后去道歉，他会说‘我没被说什么啊’，然后用无偿的爱包容我。所以与其说是回报，不如说是忠诚。他是我人生中非常重要的人。」</p><p>● 你说话时，很少只以“我”为主语，总是包含BE:FIRST或BMSG。这种不以自我为中心的存在，让这个个性强烈的团体走到了今天。</p><p>「如果真是这样就好了。」</p><p>● 在“BMSG FES&#39;25”开场，你和SKY-HI并肩演唱“GRAND CHAMP”的画面，让人很有感触。</p><p>「是副歌那段吧。」</p><p>● 对。你那种“做个麻烦的人”的意识，现在已经扩展到整个BMSG了。</p><p>「现在人越来越多，包括练习生和员工。我有时候会想，如果我消失了，是不是也没人发现。」</p><p>● 也许你自己会这么想，但绝对不是那样。反而你是最不能缺的人。</p><p>「看着工作人员为BE:FIRST努力，我也会想更努力。虽然也想和他们更亲近，但BE:FIRST这几年名气变大了，大家会保持一种‘辛苦了！’的距离感，有点寂寞。所以我会特意在满身大汗的时候过去（笑），就是以最真实的状态。」</p><p>● 虽然你说自己是“被讨厌的角色”，但其实没人讨厌你。</p><p>「是吗？不过来找我咨询的后辈确实变多了，这点很开心。他们会约我吃饭，还会具体给时间安排。吃饭时我还会问‘找我真的可以吗？’（笑）。在健身房也会有人随便来聊，这让我很开心。」</p><p>● 随着组织变大，各艺人与社长的距离也和你们当初不同了。</p><p>「是的。我可以去社长家聊天、顺便拿点衣服回来（笑），但后辈可能不太能这样。其实我觉得社长是很欢迎的。」</p><p>● 你一直坚持做那个“麻烦的人”，反而成了不可替代的存在。</p><p>「这其实是社长98%，我大概2%吧（笑）。我只是那2%负责挥旗的。哦，我今天穿的衣服也是社长给的（笑）。」</p><p>●（笑）那未来呢？无论是团队还是个人。</p><p>「一直以来我都有这个想法，就是希望能把自己的意志和想法更多地融入音乐里。那就必须更认真学习制作。虽然之前也参与过旋律和作词，但还没有真正自己做节拍，所以这些也必须去做。在现在这么多男团中，这正是只有我们能做到的，也是作为艺人该做的事。」</p><p>● 今天聊了很多“角色”，但我觉得作为创作者的LEO还没完全展现出来。</p><p>「是的，而且其他成员也都有这一面，很期待。另外，虽然面向海外很重要，但我也希望作为日本人，把日语歌曲做好。正因为想走向世界，才更要坚持用日语表达。」</p>',75)])])}const F=a(n,[["render",B]]);export{T as __pageData,F as default};
